/* FINAL VESTIGE VISUAL SYSTEM v3 — CINEMATIC INTERACTION LAYER */
html { scroll-behavior: smooth; }
body { background: #0C0D0D; background-image: radial-gradient(circle at 18% 0%,rgba(184,149,94,.05),transparent 32%), radial-gradient(circle at 82% 16%,rgba(255,255,255,.025),transparent 26%); color: #D8D2C7; }
::selection { background: #B8955E; color: #0C0D0D; }
a { text-underline-offset: .22em; transition: color .2s ease, text-decoration-color .2s ease, opacity .2s ease; }
a:hover { color: #C7A66C; }
a:focus-visible,.wp-block-button__link:focus-visible,input:focus-visible,button:focus-visible { outline: 2px solid #C7A66C; outline-offset: 4px; }
.wp-block-button__link { transition: transform .2s ease, box-shadow .2s ease, background-color .2s ease, color .2s ease; }
.wp-block-button__link:hover { transform: translateY(-2px); box-shadow: 0 10px 28px rgba(0,0,0,.24); }
.fv-site-header { position: sticky; top: 0; z-index: 999; background: rgba(10,11,11,.88) !important; box-shadow: 0 10px 34px rgba(0,0,0,.12); }
.fv-site-header:after { content: ''; position: absolute; left: 0; right: 0; bottom: -1px; height: 1px; background: linear-gradient(90deg,transparent,rgba(184,149,94,.52),transparent); }
header .wp-block-navigation-item__content { position: relative; text-decoration: none !important; }
header .wp-block-navigation-item__content:after { content: ''; position: absolute; left: 0; right: 100%; bottom: -5px; height: 1px; background: #B8955E; transition: right .22s ease; }
header .wp-block-navigation-item__content:hover:after,header .current-menu-item>.wp-block-navigation-item__content:after { right: 0; }
.fv-reading-progress { position: fixed !important; top: 0; left: 0; width: 100%; height: 2px; z-index: 1200; pointer-events: none; background: linear-gradient(90deg,#B8955E,#D6B97E); transform-origin: 0 50%; transform: scaleX(0); }
@supports (animation-timeline:scroll()) { .fv-reading-progress { animation: fv-progress linear; } @keyframes fv-progress { to { transform: scaleX(1); } } }
.fv-article-shell { position: relative; }
.fv-article-shell:before { content: ''; position: absolute; top: 0; left: max(18px,calc((100vw - 1180px)/2)); width: 46px; height: 1px; background: #B8955E; }
.fv-article-masthead { position: relative; padding-bottom: clamp(30px,4vw,50px); border-bottom: 1px solid #2A2927; }
.fv-article-masthead .wp-block-post-title { max-width: 1080px; text-wrap: balance; text-shadow: 0 12px 40px rgba(0,0,0,.16); }
.fv-article-meta { text-transform: uppercase; letter-spacing: .08em; }
.fv-article-body { counter-reset: fv-section; }
.fv-article-body>p:first-of-type { font-size: clamp(19px,2vw,23px); line-height: 1.72; color: #E5DED2; }
.fv-article-body>p:first-of-type:first-letter { float: left; font-family: Georgia,'Times New Roman',serif; font-size: 4.25em; line-height: .82; padding: .08em .11em 0 0; color: #C7A66C; }
.fv-article-body>h2 { counter-increment: fv-section; position: relative; margin-top: clamp(54px,7vw,88px); }
.fv-article-body>h2:before { content: counter(fv-section,decimal-leading-zero); display: block; margin-bottom: 10px; font: 700 10px/1 Inter,sans-serif; letter-spacing: .18em; color: #777169; }
.fv-article-body>h2:after { content: ''; display: block; width: 40px; height: 1px; margin-top: 15px; background: #B8955E; }
.fv-article-body>p { line-height: 1.78; }
.fv-article-body>.wp-block-image.alignwide { margin-top: clamp(38px,5vw,64px); margin-bottom: clamp(38px,5vw,64px); box-shadow: 0 24px 70px rgba(0,0,0,.22); }
.wp-block-image { overflow: hidden; }
.wp-block-image img,.wp-block-cover img { transition: transform .55s cubic-bezier(.2,.7,.2,1), filter .35s ease; }
.wp-block-image:hover img { transform: scale(1.012); filter: contrast(1.02); }
.wp-element-caption { border-left: 1px solid #3A3833; padding-left: 12px; margin-top: 10px; color: #908A80 !important; font-size: 12px !important; line-height: 1.55; }
.fv-dossier { margin-top: 48px; padding: clamp(24px,4vw,42px); background: linear-gradient(180deg,rgba(20,21,20,.98),rgba(12,13,13,.98)); border: 1px solid #2A2927; box-shadow: inset 3px 0 0 #B8955E, 0 22px 60px rgba(0,0,0,.16); }
.fv-dossier a { display: inline-block; text-decoration-color: rgba(184,149,94,.4); transition: transform .2s ease, color .2s ease; }
.fv-dossier a:hover { transform: translateX(3px); }
.fv-pullquote { position: relative; margin: clamp(38px,6vw,78px) auto; padding: clamp(28px,4vw,48px) clamp(22px,4vw,56px); border-top: 1px solid #B8955E; border-bottom: 1px solid #2A2927; font-family: Georgia,'Times New Roman',serif; font-size: clamp(27px,3.3vw,46px); line-height: 1.16; color: #F4EFE6; }
.fv-vestige { margin-top: 56px; padding: clamp(32px,5vw,60px); background: linear-gradient(135deg,#171816,#0E0F0F); border: 1px solid #2A2927; box-shadow: 0 26px 80px rgba(0,0,0,.3); position: relative; }
.fv-vestige:before { content: 'THE FINAL VESTIGE'; display: block; margin-bottom: 18px; font: 700 10px/1.2 Inter,sans-serif; letter-spacing: .2em; color: #B8955E; }
.fv-fieldnote { padding: 28px 30px; border-left: 2px solid #B8955E; background: rgba(184,149,94,.055); }
.fv-eyebrow { font: 700 11px/1.2 Inter,sans-serif; letter-spacing: .16em; text-transform: uppercase; color: #B8955E; }
.fv-archive-cta { background: linear-gradient(180deg,rgba(20,21,20,.88),rgba(12,13,13,.35)); border: 1px solid #2A2927; padding: clamp(26px,4vw,42px) !important; box-shadow: 0 20px 60px rgba(0,0,0,.16); }
.page-id-6 .wp-block-cover.alignfull { position: relative; }
.page-id-6 .wp-block-cover.alignfull:after { content: ''; position: absolute; top: 0; right: 0; bottom: 0; left: 0; background: linear-gradient(90deg,rgba(8,9,9,.25),transparent 48%), linear-gradient(0deg,rgba(8,9,9,.72),transparent 52%); pointer-events: none; z-index: 1; }
.page-id-6 .wp-block-cover__inner-container { position: relative; z-index: 2; }
