.page-id-6 .wp-block-cover .wp-block-buttons { margin-top: 26px; }
.page-id-6 .fv-latest-grid>li { transition: transform .28s ease, border-color .28s ease; }
.page-id-6 .fv-latest-grid>li:hover { transform: translateY(-5px); border-color: #B8955E; }
.page-id-6 .wp-block-group.alignfull.has-background .wp-block-column h3 a { display: inline-flex; align-items: center; gap: 8px; text-decoration: none; }
.page-id-6 .wp-block-group.alignfull.has-background .wp-block-column h3 a:after { content: '→'; font-family: Inter,sans-serif; font-size: .72em; color: #B8955E; opacity: 0; transform: translateX(-5px); transition: opacity .2s ease,transform .2s ease; }
.page-id-6 .wp-block-group.alignfull.has-background .wp-block-column h3 a:hover:after { opacity: 1; transform: translateX(0); }
.fv-dispatch,.page-id-6 #dispatch,.page-id-8 #dispatch { position: relative; overflow: hidden; background: linear-gradient(115deg,#B8955E 0%,#A78250 55%,#8E6E43 100%) !important; color: #0C0D0D; }
.fv-dispatch:before,.page-id-6 #dispatch:before,.page-id-8 #dispatch:before { content: ''; position: absolute; width: 520px; height: 520px; border: 1px solid rgba(12,13,13,.12); border-radius: 50%; right: -180px; top: -250px; }
.fv-dispatch:after,.page-id-6 #dispatch:after,.page-id-8 #dispatch:after { content: ''; position: absolute; width: 280px; height: 280px; border: 1px solid rgba(12,13,13,.1); border-radius: 50%; left: -90px; bottom: -170px; }
.fv-dispatch>.wp-block-group,.page-id-6 #dispatch>.wp-block-group,.page-id-8 #dispatch>.wp-block-group { position: relative; z-index: 2; }
.page-id-7 .wp-block-columns .wp-block-column>.wp-block-group { position: relative; min-height: 100%; overflow: hidden; transition: transform .25s ease,border-color .25s ease,box-shadow .25s ease,background .25s ease; }
.page-id-7 .wp-block-columns .wp-block-column>.wp-block-group:before { content: ''; position: absolute; top: 0; left: 0; width: 0; height: 2px; background: #B8955E; transition: width .28s ease; }
.page-id-7 .wp-block-columns .wp-block-column>.wp-block-group:hover { transform: translateY(-4px); border-color: #4A463F !important; background: #151615 !important; box-shadow: 0 20px 55px rgba(0,0,0,.22); }
.page-id-7 .wp-block-columns .wp-block-column>.wp-block-group:hover:before { width: 100%; }
.page-id-7 .wp-block-search__inside-wrapper { border: 1px solid #3A3833 !important; background: #0F1010; padding: 6px; }
.page-id-7 .wp-block-search__input { background: transparent !important; color: #F4EFE6 !important; border: 0 !important; }
.page-id-7 .wp-block-search__button { background: #B8955E !important; color: #0C0D0D !important; border: 0 !important; }
@supports (animation-timeline:view()) { .fv-article-body>.wp-block-image,.fv-dossier,.fv-pullquote,.fv-vestige,.fv-fieldnote,.fv-latest-grid>li { animation: fv-reveal linear both; } @keyframes fv-reveal { from { opacity: .35; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } } }
@media(max-width:781px) { html { scroll-behavior:auto; } .fv-site-header { position:sticky; top:0; } .fv-article-shell:before { left:20px; } .fv-article-body>p:first-of-type { font-size:19px; } .fv-article-body>p:first-of-type:first-letter { font-size:3.6em; } .fv-pullquote { padding-left:20px; padding-right:20px; } .fv-dossier,.fv-vestige { margin-left:0; margin-right:0; } .page-id-6 .wp-block-cover.alignfull { min-height:68vh !important; } .page-id-6 .wp-block-cover h1 { font-size:clamp(40px,12vw,58px) !important; } .page-id-6 .wp-block-cover .wp-block-buttons { gap:10px; } .wp-block-button__link { min-height:44px; display:inline-flex; align-items:center; } .fv-dispatch { padding-left:18px !important; padding-right:18px !important; } }
@media(max-width:430px) { body { font-size:16px; } .fv-article-masthead .wp-block-post-title { font-size:clamp(39px,11.5vw,52px) !important; } .fv-article-meta { font-size:10px !important; } .page-id-6 .wp-block-cover.alignfull { min-height:64vh !important; } .page-id-6 .wp-block-cover h1 { line-height:.98; } .wp-block-navigation__responsive-container.is-menu-open { padding:24px !important; background:#0A0B0B !important; } }
@media(prefers-reduced-motion:reduce) { html { scroll-behavior:auto !important; } *,:before,:after { animation:none !important; transition:none !important; } .fv-reading-progress { display:none !important; } }

