.fv-home-lead-image img{display:block;width:100%;height:auto;max-height:70vh;object-fit:contain}
.fv-home-recent-rail{min-width:0;padding-left:clamp(24px,3vw,38px);border-left:1px solid #34322E}
.fv-home-recent-rail>h2{margin:0 0 4px;font-size:clamp(23px,2vw,29px);font-weight:400;line-height:1.1}
.fv-home-rail-list{margin:0;padding:0;list-style:none}
.fv-home-rail-list>li{margin:0;padding:20px 0;border-top:1px solid #292927}
.fv-home-rail-entry h3{margin:7px 0 10px;font-size:clamp(21px,1.8vw,27px);line-height:1.1;text-wrap:balance}
.fv-home-rail-entry h3 a{color:#F4EFE6;text-decoration:none}
.fv-home-rail-entry h3 a:hover,.fv-home-rail-entry h3 a:focus-visible{color:#C7A66C;text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:4px}
.fv-home-rail-entry .fv-stream-taxonomy{font-size:10px}
.fv-home-rail-entry .fv-stream-meta{color:#908A80;font-size:10px;letter-spacing:.01em;text-transform:none}
.fv-home-latest,.fv-home-research-desk{padding-top:clamp(52px,6vw,80px);padding-bottom:clamp(44px,5vw,68px)}
.fv-home-recent-grid{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:clamp(20px,3vw,32px)!important;margin-top:4px}
.fv-home-recent-grid>li{margin:0;min-width:0}
.fv-home-recent-card{height:100%;padding-bottom:24px;border-bottom:1px solid #34322E}
.fv-home-recent-thumb{aspect-ratio:16/10;margin:0 0 18px;background:#0C0D0D;border:1px solid #34322E;overflow:hidden}
.fv-home-recent-thumb a{display:block;width:100%;height:100%}
.fv-home-recent-thumb img{width:100%;height:100%;object-fit:contain}
.fv-home-recent-card h3{margin:10px 0 12px;font-size:clamp(25px,2.35vw,33px);line-height:1.08}
.fv-home-recent-card h3 a{color:#F4EFE6;text-decoration:none}
.fv-home-recent-card p{color:#AAA49A;line-height:1.65}
.fv-home-taxonomy-shell{position:relative;background:#101111!important}
.fv-home-taxonomy-shell:after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,rgba(184,149,94,.20),transparent);pointer-events:none}
.fv-home-taxonomy-grid{gap:0!important}
.fv-home-taxonomy-grid>li{margin:0}
.fv-home-taxonomy-item{position:relative;min-height:70px;padding:8px 18px;justify-content:center;border-left:1px solid #292927}
.fv-home-taxonomy-grid>li:first-child .fv-home-taxonomy-item{border-left:0}
.fv-home-taxonomy-name{margin:0;font-size:11px;font-weight:700;line-height:1.2;letter-spacing:.14em;text-transform:uppercase}
.fv-home-taxonomy-name a{display:inline-flex;align-items:center;min-height:44px;color:#D8D2C7;text-decoration:none}
.fv-home-taxonomy-meta{margin-top:-6px;gap:5px;color:#908A80;font-size:10px;font-weight:700;line-height:1.25;letter-spacing:.11em;text-transform:uppercase}
.fv-home-taxonomy-meta p{margin:0}
.fv-home-taxonomy-count{color:#B8955E;font-size:10px}
.page-id-6 .fv-home-trails{padding-top:clamp(52px,6vw,80px);padding-bottom:clamp(44px,5vw,68px)}
.page-id-6 .fv-home-trails>.wp-block-group>p:not(.fv-eyebrow){max-width:800px}
.page-id-6 .fv-home-trail-grid{gap:clamp(18px,3vw,30px)!important}
.page-id-6 .fv-home-trail-card{height:100%;padding:clamp(22px,2.7vw,30px);background:#111212;border:1px solid #34322E;border-left:2px solid #B8955E}
.page-id-6 .fv-home-trail-card h3 a{color:#F4EFE6;text-decoration:none}
.page-id-6 .fv-home-trail-description{color:#AAA49A;font-size:14px;line-height:1.65}
.page-id-6 .fv-home-desk-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));margin-top:22px;border-top:1px solid #34322E;border-bottom:1px solid #34322E}
.page-id-6 .fv-home-desk-card{padding:24px;border-right:1px solid #34322E}
.page-id-6 .fv-home-desk-card:last-child{border-right:0}
.page-id-6 .fv-home-desk-meta{color:#B8955E;font-size:9px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.page-id-6 .fv-home-desk-card p{color:#AAA49A;font-size:14px;line-height:1.65}
.page-id-6 .fv-home-method{margin-top:clamp(44px,5vw,68px);margin-bottom:clamp(44px,5vw,68px);padding:clamp(26px,3.5vw,38px);background:#111212;border:1px solid #34322E;border-left:2px solid #B8955E}
.page-id-6 .fv-home-method>p{max-width:760px;color:#AAA49A;line-height:1.7}
@media(max-width:1180px){
 .fv-home-front{grid-template-columns:1fr;gap:34px}
 .fv-home-recent-rail{padding:24px 0 0;border-left:0;border-top:1px solid #34322E}
 .fv-home-rail-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0 28px}
 .fv-home-rail-list>li{padding:18px 0;border-top:0;border-bottom:1px solid #292927}
 .page-id-6 .fv-home-desk-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
 .page-id-6 .fv-home-desk-card:nth-child(2){border-right:0}
 .page-id-6 .fv-home-desk-card:nth-child(-n+2){border-bottom:1px solid #34322E}
}
@media(max-width:1000px){
 .fv-home-recent-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}
 .fv-home-taxonomy-grid{grid-template-columns:repeat(3,minmax(0,1fr))!important}
}
@media(max-width:900px){
 .fv-home-lead{grid-template-columns:1fr}
 .fv-home-lead:not(:has(.fv-home-lead-image img)){grid-template-columns:1fr}
 .fv-home-lead-copy{max-width:820px}
 .fv-home-rail-list{grid-template-columns:1fr}
}
@media(max-width:680px){
 .fv-home-lead-shell{padding:34px 18px 40px!important}
 .fv-home-front{gap:28px}
 .fv-home-lead{gap:24px}
 .fv-home-lead-title{font-size:clamp(40px,11vw,56px)}
 .fv-home-recent-rail{padding-top:20px}
 .fv-home-rail-entry h3{font-size:clamp(23px,7vw,29px)}
 .fv-home-latest,.fv-home-research-desk{padding-top:44px;padding-bottom:46px}
 .fv-home-recent-grid,.page-id-6 .fv-home-trail-grid,.page-id-6 .fv-home-desk-grid{grid-template-columns:1fr!important}
 .page-id-6 .fv-home-desk-card{border-right:0;border-bottom:1px solid #34322E}
 .page-id-6 .fv-home-desk-card:last-child{border-bottom:0}
 .page-id-6 .fv-home-method{padding:24px 20px;margin-top:40px;margin-bottom:44px}
}
@media(max-width:520px){
 .fv-home-taxonomy-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}
 .fv-home-taxonomy-item{min-height:66px;padding:7px 12px}
}
@media(prefers-reduced-motion:reduce){
 .fv-home-lead-title a,.fv-home-rail-entry h3 a{transition:none!important}
}

/* FINAL VESTIGE — MISSING-ART PLACEHOLDER SYSTEM */
.fv-home-recent-thumb:not(:has(img)){display:flex;align-items:center;justify-content:center;background:repeating-linear-gradient(135deg,rgba(184,149,94,.05) 0 1px,transparent 1px 14px),linear-gradient(160deg,#111212,#0A0B0B);position:relative}
.fv-home-recent-thumb:not(:has(img))::before{content:"";width:34%;aspect-ratio:1;border:1px solid rgba(184,149,94,.35);border-radius:50%}
.fv-home-recent-thumb:not(:has(img))::after{content:"FV";position:absolute;font:700 11px/1 Inter,sans-serif;letter-spacing:.18em;color:rgba(184,149,94,.55)}

/* FINAL VESTIGE — PRINT STYLESHEET, EXTENDED TO STANDARD ARTICLES */
@media print{
.fv-article-shell{max-width:none;padding:0!important}
.fv-article-masthead .wp-block-post-title,.fv-article-meta,.fv-provenance,.fv-article-body h2,.fv-article-body p,.fv-article-body li,.fv-article-body a{color:#111!important;text-shadow:none!important}
.fv-dossier,.fv-pullquote,.fv-vestige,.fv-fieldnote{background:transparent!important;box-shadow:none!important;border-color:#aaa!important}
.fv-article-body>h2{break-after:avoid;page-break-after:avoid}
.fv-article-body>p,.fv-article-body>li{orphans:3;widows:3}
.fv-article-body>.wp-block-image.alignwide{box-shadow:none!important}
.fv-archive-cta{display:none!important}
}
